wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use std::collections::BTreeSet;

use crate::aap::caps::state_rw;
use crate::{PublishedDigest, RunReport};

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        if published.published {
            // Deduplicate so `recorded` counts distinct ids, not list entries.
            let ids: BTreeSet<&str> = published.considered.iter().map(String::as_str).collect();
            for id in ids {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
